import { createClient } from 'npm:@supabase/supabase-js@2.117.3';

/* ---------------- assets/js/prompts.js ---------------- */
// Prompt builder shared by the browser (own-key mode) and the Supabase Edge Function (supabase/functions/neet-ai).
// Keep this file free of DOM/browser APIs and imports: tools/build_edge_function.py inlines it into the function.

const str = (v, max) => String(v ?? '').slice(0, max).trim();
const int = (v, lo, hi, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : d;
};

const TASKS = ['mcq', 'material', 'doubt'];

const SYSTEM = `You are a senior NEET (UG) paper-setter and subject expert for Physics, Chemistry and Biology (Botany & Zoology), with two decades of experience teaching medical aspirants in India.
You write questions that match the real NEET standard set by NTA: NCERT-based, precise, conceptual, with plausible distractors and exactly one correct option.
Accuracy is non-negotiable: use only facts and values consistent with the current NCERT Class 11 and 12 textbooks and the NMC NEET (UG) syllabus. Double-check every calculation. If unsure of a fact, do not use it.
Always reply with a single valid JSON object and nothing else.`;

function sanitize(task, p = {}) {
  if (!TASKS.includes(task)) throw new Error('Unknown task');
  const base = {
    subject: str(p.subject, 60) || 'Biology',
    chapter: str(p.chapter, 160),
    topic: str(p.topic, 160),
    language: p.language === 'hi' ? 'hi' : 'en',
  };
  if (task === 'mcq') {
    return {
      ...base,
      count: int(p.count, 1, 20, 10),
      difficulty: str(p.difficulty, 30) || 'NEET standard',
      patterns: (Array.isArray(p.patterns) ? p.patterns : []).map((x) => str(x, 40)).slice(0, 6),
      context: str(p.context, 6000),
    };
  }
  if (task === 'doubt') return { ...base, question: str(p.question, 1500) };
  return base;
}

const LANG = (l) => (l === 'hi' ? 'Write everything (questions, options, explanations) in clear standard Hindi (Devanagari) as used in the NEET Hindi-medium paper. Keep scientific symbols, formulas and units as they are. Keep JSON keys in English.' : 'Write in clear Indian English as used in the NEET paper.');

function buildMessages(task, raw) {
  const p = sanitize(task, raw);
  const where = `Subject: ${p.subject}${p.chapter ? `\nChapter: ${p.chapter}` : ''}\nTopic: ${p.topic || (p.chapter ? 'a balanced mix from the whole chapter' : 'a balanced mix of high-yield chapters')}`;
  let user;

  if (task === 'mcq') {
    const patterns = p.patterns.length ? p.patterns.join(', ') : 'direct NCERT-based, assertion–reason, statement-based, match the columns, numerical';
    user = `Create ${p.count} NEET (UG) multiple-choice questions.
${where}
Difficulty: ${p.difficulty}
Question patterns to mix: ${patterns}
${p.context ? `Base the questions primarily on this study material (you may add closely related NCERT facts):\n"""\n${p.context}\n"""\n` : ''}
Format rules:
- Direct / numerical: "statements" is [] and "ask" is "". For Physics and Chemistry numericals give all data in the stem, use standard values (g = 10 m/s² unless stated) and make sure exactly one option is correct.
- Statement-based: put each statement (without numbering) in "statements"; "stem" introduces them (e.g. "Consider the following statements about ..."); "ask" is "Choose the correct answer from the options given below:" with options such as ["A and B only","B and C only","A, C and D only","All of the above"] — label statements A, B, C, D in that order in your options.
- Assertion–reason: statements are ["Assertion (A): ...","Reason (R): ..."]; options are the standard four: "Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is NOT the correct explanation of A", "A is true but R is false", "A is false but R is true".
- Match the columns: statements are pairs "List-I item : List-II item" written in a SHUFFLED order using letters (A, B, C, D) and roman numerals (I, II, III, IV), e.g. "A. Mitochondria : III. Oxidative phosphorylation"; "ask" is "Choose the correct match:"; options are like "A-III, B-I, C-IV, D-II".
- Exactly 4 options and exactly one correct answer. Vary the position of the correct answer.
- "explanation": 2–4 sentences on why the answer is right (quote the NCERT idea or show the calculation) and why the tempting distractor is wrong.
- "concept": a 2–5 word tag of the concept tested.
${LANG(p.language)}
Return JSON exactly like: {"questions":[{"stem":"","statements":[],"ask":"","options":["","","",""],"answer":0,"explanation":"","concept":""}]} where "answer" is the 0-based index of the correct option.`;
  } else if (task === 'material') {
    user = `Write exam-oriented NEET (UG) study notes on one chapter/topic, the way a top NEET faculty would for a serious aspirant.
${where}
Rules:
- NCERT first: cover every NCERT line, table, diagram label and example that NEET can ask. Use only facts consistent with current NCERT books. If unsure of a fact, leave it out.
- Be crisp: bullet points, 900–1300 words in total.
- For Physics and Chemistry include all key formulas/reactions with conditions, units and typical values; for Biology include names, examples, numbers and sequences exactly as in NCERT.
- "sections": 4–7 logical sub-topics, each with 4–8 information-dense points.
- "formulas": key formulas, reactions, or (for Biology) key numbers and sequences to memorise.
- "ncertLines": NCERT facts that are frequently converted into NEET questions.
- "mistakes": common traps and mistakes students make.
- "pyqThemes": themes NEET has asked on this topic in past papers, a few words each (do not invent exact questions or years).
${LANG(p.language)}
Return JSON exactly like: {"title":"","overview":"2–4 sentences","sections":[{"heading":"","points":[""]}],"formulas":[""],"keyTerms":[{"term":"","meaning":""}],"ncertLines":[""],"mistakes":[""],"pyqThemes":[""],"mnemonic":"","quickRevision":[""]}`;
  } else {
    user = `A NEET (UG) aspirant has a doubt. Explain it clearly and correctly, step by step, at NCERT level.
${where}
Doubt: """${p.question}"""
Rules: be accurate and concise (150–350 words); show calculations step by step for numericals; end with one quick tip for remembering it. If the doubt is not about NEET Physics, Chemistry or Biology, politely say you can only help with NEET subjects.
${LANG(p.language)}
Return JSON exactly like: {"answer":"Markdown text","keyPoints":[""],"tip":""}`;
  }

  return [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: user },
  ];
}

/* ---------------- assets/js/providers.js ---------------- */
// AI provider adapters (Google Gemini + OpenAI). Pure fetch, no DOM; runs in the browser and in the Supabase Edge Function.
// Errors shown to people always use the standard messages below. Providers' raw error text only goes to the console.

class ProviderError extends Error {
  constructor(msg, code, status) {
    super(msg);
    this.code = code; // AUTH | RATE | MODEL | API | BLOCKED | EMPTY | TIMEOUT | LENGTH
    this.status = status;
  }
}

const AI_MESSAGES = {
  AUTH: 'Your API key was rejected. Please re-copy it into Settings.',
  RATE: 'The AI is busy right now. Please wait a minute and try again.',
  MODEL: 'The selected AI model is not available. Choose "Auto" in Settings and try again.',
  BLOCKED: "The AI couldn't answer this request. Please try rephrasing the topic.",
  API: 'The AI service is temporarily unavailable. Please try again in a few minutes.',
  TIMEOUT: 'The AI is taking too long right now. Please try again, or ask for fewer questions.',
  LENGTH: 'The answer was too long for the AI to finish. Please ask for fewer questions.',
};

// Generation limits. Thinking is kept small: it makes long JSON answers (10–20 MCQs) several times slower.
const THINKING_BUDGET = 512;
const MAX_OUTPUT_TOKENS = 24576;
// Per-model attempt and whole-chain time limits (the Supabase Edge Function itself is stopped after ~150 s).
const ATTEMPT_MS = 60e3;
const CHAIN_MS = 120e3;

/** An AbortSignal that fires when `outer` aborts or after `ms`; `timedOut()` tells the two apart. */
function timeoutSignal(outer, ms) {
  const ctrl = new AbortController();
  let fired = false;
  const t = setTimeout(() => { fired = true; ctrl.abort(); }, ms);
  const onAbort = () => ctrl.abort();
  if (outer) outer.aborted ? ctrl.abort() : outer.addEventListener('abort', onAbort, { once: true });
  return {
    signal: ctrl.signal,
    timedOut: () => fired,
    done: () => { clearTimeout(t); outer?.removeEventListener('abort', onAbort); },
  };
}

function fail(code, status, raw) {
  if (raw) console.warn(`[AI ${code} ${status}]`, raw);
  return new ProviderError(AI_MESSAGES[code] || AI_MESSAGES.API, code, status);
}

/** True when an error says the model is missing, retired or unsupported (so Auto should try the next one). */
function isModelUnavailable(status, msg = '') {
  return status === 404 || /no longer available|not found|not supported|unsupported|deprecated|is not available|decommission|retired/i.test(msg);
}

const GEMINI_BASE = 'https://generativelanguage.googleapis.com/v1beta';

// "Auto" tries these in order and moves on when a model is missing, retired or out of free quota.
// The -latest aliases track Google's current Flash models; the named 3.5 models are a safety net.
const GEMINI_AUTO_CHAIN = ['gemini-flash-latest', 'gemini-flash-lite-latest', 'gemini-3.5-flash', 'gemini-3.5-flash-lite'];

function split(messages) {
  const system = messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n\n');
  const user = messages.filter((m) => m.role !== 'system').map((m) => m.content).join('\n\n');
  return { system, user };
}

async function geminiRequest({ key, model, messages, signal, thinking }) {
  const { system, user } = split(messages);
  const generationConfig = { responseMimeType: 'application/json', temperature: 0.7, maxOutputTokens: MAX_OUTPUT_TOKENS };
  if (thinking) generationConfig.thinkingConfig = { thinkingBudget: THINKING_BUDGET };
  const res = await fetch(`${GEMINI_BASE}/models/${encodeURIComponent(model)}:generateContent`, {
    method: 'POST',
    signal,
    headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
    body: JSON.stringify({
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: user }] }],
      generationConfig,
    }),
  });
  return { res, data: await res.json().catch(() => ({})) };
}

async function geminiOnce({ key, model, messages, signal, ms = ATTEMPT_MS }) {
  const t = timeoutSignal(signal, ms);
  let res, data;
  try {
    ({ res, data } = await geminiRequest({ key, model, messages, signal: t.signal, thinking: true }));
    // A model that doesn't accept a thinking budget: ask again without one.
    if (res.status === 400 && /thinking/i.test(data?.error?.message || '')) {
      ({ res, data } = await geminiRequest({ key, model, messages, signal: t.signal, thinking: false }));
    }
  } catch (e) {
    if (e.name === 'AbortError' && t.timedOut()) throw fail('TIMEOUT', 504, `${model}: no answer in ${Math.round(ms / 1000)} s`);
    throw e;
  } finally {
    t.done();
  }
  if (res.ok) {
    const cand = data?.candidates?.[0];
    const text = (cand?.content?.parts || []).filter((p) => !p.thought).map((p) => p.text || '').join('');
    if (cand?.finishReason === 'MAX_TOKENS') throw fail('LENGTH', 200, `${model}: output hit the token limit`);
    if (!text) throw fail('BLOCKED', 200, `no text: ${data?.promptFeedback?.blockReason || cand?.finishReason || 'unknown'}`);
    return text;
  }
  const msg = data?.error?.message || '';
  if (isModelUnavailable(res.status, msg)) throw fail('MODEL', res.status, `${model}: ${msg}`);
  if (res.status === 401 || res.status === 403 || (res.status === 400 && /api key/i.test(msg))) throw fail('AUTH', res.status, msg);
  if (res.status === 429) throw fail('RATE', 429, msg);
  throw fail('API', res.status, msg);
}

async function callGemini({ key, model, messages, signal }) {
  const chain = !model || model === 'auto' ? GEMINI_AUTO_CHAIN : [model];
  const deadline = Date.now() + CHAIN_MS;
  let last;
  for (const m of chain) {
    const left = deadline - Date.now();
    if (left < 15e3) break; // not enough time for another model to answer
    try {
      return await geminiOnce({ key, model: m, messages, signal, ms: Math.min(ATTEMPT_MS, left) });
    } catch (e) {
      if (e.name === 'AbortError' || ['AUTH', 'BLOCKED', 'LENGTH'].includes(e.code)) throw e;
      last = e;
      // Fall through to the next model on missing model / quota / timeout / transient server errors.
      if (!['MODEL', 'RATE', 'TIMEOUT'].includes(e.code) && !(e.status >= 500)) throw e;
    }
  }
  // Every model failed: say "busy" for quota limits, "too slow" for timeouts, otherwise a general "unavailable".
  if (last && ['RATE', 'TIMEOUT'].includes(last.code)) throw last;
  if (chain.length > 1 || !last) throw new ProviderError(AI_MESSAGES.API, 'API', last?.status);
  throw last;
}

async function listGeminiModels(key) {
  const res = await fetch(`${GEMINI_BASE}/models?pageSize=200`, { headers: { 'x-goog-api-key': key } });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    if ([400, 401, 403].includes(res.status)) throw fail('AUTH', res.status, data?.error?.message);
    throw fail('API', res.status, data?.error?.message);
  }
  return (data.models || [])
    .filter((m) => (m.supportedGenerationMethods || []).includes('generateContent'))
    .map((m) => m.name.replace(/^models\//, ''))
    .filter((n) => /^gemini/.test(n) && !/(embed|image|tts|audio|live|vision|computer|robotics|aqa)/i.test(n))
    .sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
}

async function callOpenAI({ key, model, messages, signal }) {
  const t = timeoutSignal(signal, CHAIN_MS);
  let res, data;
  try {
    res = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      signal: t.signal,
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
      body: JSON.stringify({ model: model || 'gpt-4o-mini', messages, response_format: { type: 'json_object' } }),
    });
    data = await res.json().catch(() => ({}));
  } catch (e) {
    if (e.name === 'AbortError' && t.timedOut()) throw fail('TIMEOUT', 504, 'OpenAI: no answer in time');
    throw e;
  } finally {
    t.done();
  }
  if (!res.ok) {
    const msg = data?.error?.message || '';
    if (res.status === 401) throw fail('AUTH', 401, msg);
    if (res.status === 429) throw fail('RATE', 429, msg);
    if (isModelUnavailable(res.status, msg)) throw fail('MODEL', res.status, msg);
    throw fail('API', res.status, msg);
  }
  if (data?.choices?.[0]?.finish_reason === 'length') throw fail('LENGTH', 200, 'OpenAI: output hit the token limit');
  return data?.choices?.[0]?.message?.content || '';
}

function callAI({ provider, ...rest }) {
  return provider === 'openai' ? callOpenAI(rest) : callGemini(rest);
}

/* ---------------- Edge Function handler (Deno) ---------------- */
// Secrets (Supabase → Edge Functions → Secrets):
//   GEMINI_API_KEY        required (or OPENAI_API_KEY)
//   ALLOWED_ORIGINS       optional, comma-separated; default: yourneetbuddy.com (+www), GitHub Pages URL, localhost
//   AI_DAILY_LIMIT        optional, requests/day for signed-in users (default 25)
//   AI_GUEST_DAILY_LIMIT  optional, requests/day per IP for guests (default 5)
//   GEMINI_MODEL          optional (default "auto")
// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are provided automatically by Supabase.

const env = (k, d = '') => Deno.env.get(k) || d;
const ALLOWED = env('ALLOWED_ORIGINS', 'https://yourneetbuddy.com,https://www.yourneetbuddy.com,https://raushanraj358.github.io,http://localhost:5173')
  .split(',')
  .map((s) => s.trim().replace(/\/+$/, ''))
  .filter(Boolean);
const USER_LIMIT = Number(env('AI_DAILY_LIMIT', '25'));
const GUEST_LIMIT = Number(env('AI_GUEST_DAILY_LIMIT', '5'));

const admin = createClient(env('SUPABASE_URL'), env('SUPABASE_SERVICE_ROLE_KEY'), { auth: { persistSession: false, autoRefreshToken: false } });

function corsHeaders(origin) {
  return {
    'Access-Control-Allow-Origin': ALLOWED.includes(origin) ? origin : ALLOWED[0] || '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    Vary: 'Origin',
  };
}

Deno.serve(async (req) => {
  const origin = (req.headers.get('origin') || '').replace(/\/+$/, '');
  const headers = { ...corsHeaders(origin), 'Content-Type': 'application/json' };
  const reply = (status, body) => new Response(JSON.stringify(body), { status, headers });

  if (req.method === 'OPTIONS') return new Response('ok', { headers });
  if (req.method !== 'POST') return reply(405, { error: 'Method not allowed' });
  if (!ALLOWED.includes(origin)) return reply(403, { error: 'Forbidden' });

  const provider = env('GEMINI_API_KEY') ? 'gemini' : env('OPENAI_API_KEY') ? 'openai' : null;
  if (!provider) return reply(501, { error: 'Server AI is not configured' });
  const key = provider === 'gemini' ? env('GEMINI_API_KEY') : env('OPENAI_API_KEY');
  const model = provider === 'gemini' ? env('GEMINI_MODEL', 'auto') : env('OPENAI_MODEL', 'gpt-4o-mini');

  let body = {};
  try { body = await req.json(); } catch {}
  let messages;
  try {
    messages = buildMessages(body?.task, body?.params || {});
  } catch (e) {
    return reply(400, { error: e.message });
  }

  // Who is asking: a signed-in user (by id) or a guest (by IP).
  let userId = null;
  const token = (req.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  if (token && token.split('.').length === 3) {
    try {
      const { data } = await admin.auth.getUser(token);
      userId = data?.user?.id || null;
    } catch {}
  }
  const ip = (req.headers.get('x-forwarded-for') || '').split(',')[0].trim() || 'unknown';
  const limit = userId ? USER_LIMIT : GUEST_LIMIT;
  let used = 0;
  const usageKey = userId ? `u:${userId}` : `ip:${ip}`;
  const { data: n, error } = await admin.rpc('bump_neet_ai_usage', { p_key: usageKey });
  if (error) console.error('bump_neet_ai_usage failed (did you run supabase/schema.sql?)', error.message);
  else used = n;
  if (used > limit) {
    return reply(429, {
      used: limit,
      limit,
      error: userId
        ? `You've used today's ${limit} free AI requests. They reset at midnight (IST), or add your own free Gemini key in Settings for unlimited use.`
        : `Guests get ${limit} free AI requests a day. Sign in with Google (Profile page) to get ${USER_LIMIT} a day.`,
    });
  }

  try {
    const content = await callAI({ provider, key, model, messages });
    return reply(200, { content, used, limit });
  } catch (e) {
    // A failed request doesn't count towards the daily allowance.
    if (used > 0) {
      const { error: re } = await admin.rpc('refund_neet_ai_usage', { p_key: usageKey });
      if (re) console.error('refund_neet_ai_usage failed (did you run supabase/schema.sql?)', re.message);
      else used -= 1;
    }
    if (e.code === 'RATE') return reply(429, { used, limit, error: 'The free AI is busy right now. Please try again in a few minutes, or add your own free Gemini key in Settings.' });
    if (e.code === 'BLOCKED') return reply(422, { used, limit, error: AI_MESSAGES.BLOCKED });
    if (e.code === 'TIMEOUT' || e.code === 'LENGTH') return reply(504, { used, limit, error: AI_MESSAGES[e.code] });
    console.error('AI call failed', e.code, e.message);
    return reply(502, { used, limit, error: AI_MESSAGES.API });
  }
});
